const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const SRC_DIR = path.join(ROOT, "src", "app");
const OUT_FILE = path.join(ROOT, "public", "app.js");

const APP_PARTS = [
  "00-config-state-dom.js",
  "10-api-core.js",
  "20-chat-auth.js",
  "30-me-attendance-notes.js",
  "40-orders-list-detail.js",
  "50-settings-share.js",
  "60-events-actions.js",
  "70-photo-chat-upload.js",
  "80-order-parser-forms.js",
  "90-bootstrap-events.js",
];

const banner = [
  "// This file is generated by scripts/build-public-app.js.",
  "// Edit files in src/app instead of editing public/app.js directly.",
  "",
].join("\n");

const body = APP_PARTS.map((file) => {
  const fullPath = path.join(SRC_DIR, file);
  return [
    `// ===== ${file} =====`,
    fs.readFileSync(fullPath, "utf8").trimEnd(),
    "",
  ].join("\n");
}).join("\n");

fs.writeFileSync(OUT_FILE, `${banner}${body}`, "utf8");
console.log(`Built ${path.relative(ROOT, OUT_FILE)} from ${APP_PARTS.length} source files.`);
